package com.bank.slots;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.Logger;

// Compacts non-zero settlement amounts to the front for National Bank of India.
public class SlotCompactor {
    private static final Logger log = Logger.getLogger(SlotCompactor.class.getName());

    // Stable: non-zero amounts keep order; zeros pushed to the end. O(n), O(1).
    public void moveZerosToEnd(BigDecimal[] slots) {
        if (slots == null) return;
        int write = 0;                               // next front position to fill
        for (int scan = 0; scan < slots.length; scan++) {
            if (slots[scan].signum() != 0) {         // non-zero amount
                if (write != scan) {                 // skip redundant self-write
                    slots[write] = slots[scan];
                }
                write++;
            }
        }
        while (write < slots.length) {               // fill the tail with zeros
            slots[write++] = BigDecimal.ZERO;
        }
        log.info(() -> "Compacted slots: " + Arrays.toString(slots));
    }
}
