package com.bank.slots;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: compact Rajesh's daily settlement slots.
public class SlotDemo {
    private static final Logger log = Logger.getLogger(SlotDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BigDecimal bd(String s) { return new BigDecimal(s); }

    public static void main(String[] args) {
        SlotCompactor compactor = new SlotCompactor();

        // Rajesh (SAV2001) settlement slots; 0 marks an empty slot.
        BigDecimal[] slots = {
            bd("5000"), bd("0"), bd("12000"), bd("0"), bd("0"), bd("800")
        };
        log.info(() -> "Before: " + Arrays.toString(slots));
        compactor.moveZerosToEnd(slots);
        log.info(() -> "After (non-zeros front, order kept): " + Arrays.toString(slots));
    }
}
